import http from 'node:http';
import { DatabaseSync } from 'node:sqlite';
import { mkdirSync } from 'node:fs';
import { dirname } from 'node:path';

const databasePath = process.env.DB_PATH || 'data/workboard.sqlite';
mkdirSync(dirname(databasePath), { recursive: true });
const db = new DatabaseSync(databasePath);
db.exec(`CREATE TABLE IF NOT EXISTS projects (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL
)`);
db.exec(`PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS tasks (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  project_id INTEGER NOT NULL REFERENCES projects(id),
  title TEXT NOT NULL,
  completed INTEGER NOT NULL DEFAULT 0 CHECK (completed IN (0, 1))
)`);
const listTasks = db.prepare('SELECT id, title, completed FROM tasks WHERE project_id = ? ORDER BY id');
const createTask = db.prepare('INSERT INTO tasks (project_id, title) VALUES (?, ?)');
const updateTask = db.prepare('UPDATE tasks SET completed = ? WHERE id = ? AND project_id = ?');
const listProjects = db.prepare('SELECT id, name FROM projects ORDER BY id');
const findProject = db.prepare('SELECT id, name FROM projects WHERE id = ?');
const createProject = db.prepare('INSERT INTO projects (name) VALUES (?)');

function escapeHtml(value) {
  return String(value).replace(/[&<>"']/g, char => ({
    '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'
  })[char]);
}

function page(title, content) {
  return `<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>${escapeHtml(title)} — Workboard</title>
  <style>
    * { box-sizing: border-box; }
    body { margin: 0; background: #f3f5f8; color: #182435; font: 16px system-ui, sans-serif; }
    main { max-width: 760px; margin: 64px auto; padding: 28px; background: white; border-radius: 12px; }
    h1 { margin-top: 0; overflow-wrap: anywhere; }
    form { margin-bottom: 24px; }
    label { display: block; font-weight: 600; margin-bottom: 8px; }
    input { padding: 10px; font: inherit; width: 100%; border: 1px solid #8994a4; border-radius: 6px; margin-bottom: 12px; }
    button { font: inherit; cursor: pointer; padding: 10px 16px; border: 0; border-radius: 6px; background: #245ac7; color: white; }
    select { font: inherit; padding: 8px; margin-bottom: 16px; }
    .task-row { display: flex; align-items: center; gap: 12px; padding: 16px 0; border-top: 1px solid #dce1e8; overflow-wrap: anywhere; }
    .task-row[hidden] { display: none; }
    .task-row input { width: auto; margin: 0; flex-shrink: 0; }
    button:focus-visible, input:focus-visible, select:focus-visible { outline: 3px solid #bd7600; outline-offset: 3px; }
    .project-row { display: flex; align-items: center; justify-content: space-between; gap: 20px; padding: 16px 0; border-top: 1px solid #dce1e8; }
    .project-row span { overflow-wrap: anywhere; min-width: 0; }
    .project-row form { margin: 0; flex-shrink: 0; }
    [role=alert] { color: #a51c22; margin-bottom: 16px; }
    @media (max-width: 600px) { main { margin: 16px; padding: 20px; } }
  </style>
</head>
<body><main>${content}</main></body>
</html>`;
}

function projectsPage(error = '', name = '') {
  return page('Projects', `<h1>Workboard</h1>
    ${error ? `<div role="alert">${escapeHtml(error)}</div>` : ''}
    <form action="/projects" method="post">
      <label for="project-name">Project name</label>
      <input id="project-name" name="name" type="text" value="${escapeHtml(name)}">
      <button type="submit">Create project</button>
    </form>
    <section aria-label="Projects">${listProjects.all().map(project => `
      <div class="project-row" data-testid="project-row">
        <span>${escapeHtml(project.name)}</span>
        <form action="/projects/${project.id}" method="get"><button type="submit">Open project</button></form>
      </div>`).join('')}</section>`);
}

function projectPage(project, error = '') {
  return page(project.name, `<h1>${escapeHtml(project.name)}</h1>
    <form action="/" method="get"><button type="submit">Projects</button></form>
    <div role="alert" id="task-error">${escapeHtml(error)}</div>
    <form action="/projects/${project.id}/tasks" method="post">
      <label for="task-title">Task title</label>
      <input id="task-title" name="title" type="text">
      <button type="submit">Create task</button>
    </form>
    <label for="task-filter">Task filter</label>
    <select id="task-filter">
      <option>All</option><option>Open</option><option>Completed</option>
    </select>
    <section aria-label="Tasks">${listTasks.all(project.id).map(task => `
      <div class="task-row" data-testid="task-row">
        <input type="checkbox" aria-label="${escapeHtml(`Complete ${task.title}`)}"
          data-completion-url="/projects/${project.id}/tasks/${task.id}/completion"${task.completed ? ' checked' : ''}>
        <span>${escapeHtml(task.title)}</span>
      </div>`).join('')}</section>
    <script>
      const filter = document.getElementById('task-filter');
      function applyFilter() {
        document.querySelectorAll('[data-testid="task-row"]').forEach(row => {
          const completed = row.querySelector('input').checked;
          row.hidden = filter.value === 'Open' && completed || filter.value === 'Completed' && !completed;
        });
      }
      filter.addEventListener('change', applyFilter);
      document.querySelectorAll('[data-completion-url]').forEach(checkbox => {
        checkbox.addEventListener('change', async () => {
          const completed = checkbox.checked;
          checkbox.disabled = true;
          document.getElementById('task-error').textContent = '';
          try {
            const response = await fetch(checkbox.dataset.completionUrl, {
              method: 'POST', body: new URLSearchParams({ completed: String(completed) })
            });
            if (!response.ok) throw new Error('Completion update failed');
          } catch {
            checkbox.checked = !completed;
            document.getElementById('task-error').textContent = 'Could not save task completion. Please try again.';
          } finally {
            checkbox.disabled = false;
            applyFilter();
          }
        });
      });
    </script>`);
}

async function readForm(req) {
  let body = '';
  for await (const chunk of req) {
    body += chunk;
    if (Buffer.byteLength(body) > 1024 * 1024) {
      const error = new Error('Request too large');
      error.status = 413;
      throw error;
    }
  }
  return new URLSearchParams(body);
}

function html(res, status, content) {
  res.writeHead(status, { 'Content-Type': 'text/html; charset=utf-8' });
  res.end(content);
}

const server = http.createServer(async (req, res) => {
  try {
    const url = new URL(req.url, 'http://localhost');
    if (req.method === 'GET' && url.pathname === '/health') {
      res.writeHead(200, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ status: 'ok' }));
    } else if (req.method === 'GET' && url.pathname === '/') {
      html(res, 200, projectsPage());
    } else if (req.method === 'POST' && url.pathname === '/projects') {
      const name = ((await readForm(req)).get('name') || '').trim();
      if (!name) {
        html(res, 422, projectsPage('Project name is required'));
        return;
      }
      createProject.run(name);
      res.writeHead(303, { Location: '/' });
      res.end();
    } else if (req.method === 'GET' && /^\/projects\/\d+$/.test(url.pathname)) {
      const project = findProject.get(Number(url.pathname.split('/')[2]));
      if (!project) {
        html(res, 404, page('Not found', '<h1>Project not found</h1><form action="/"><button>Projects</button></form>'));
        return;
      }
      html(res, 200, projectPage(project));
    } else if (req.method === 'POST' && /^\/projects\/\d+\/tasks(?:\/\d+\/completion)?$/.test(url.pathname)) {
      const parts = url.pathname.split('/');
      const project = findProject.get(Number(parts[2]));
      if (!project) {
        html(res, 404, page('Not found', '<h1>Project not found</h1>'));
        return;
      }
      const form = await readForm(req);
      if (parts.length === 4) {
        const title = (form.get('title') || '').trim();
        if (!title) {
          html(res, 422, projectPage(project, 'Task title is required'));
          return;
        }
        createTask.run(project.id, title);
        res.writeHead(303, { Location: `/projects/${project.id}` });
        res.end();
      } else {
        const completed = form.get('completed');
        if (completed !== 'true' && completed !== 'false') {
          html(res, 400, page('Invalid completion', '<h1>Invalid completion state</h1>'));
          return;
        }
        const result = updateTask.run(completed === 'true' ? 1 : 0, Number(parts[4]), project.id);
        res.writeHead(result.changes ? 204 : 404);
        res.end();
      }
    } else {
      html(res, 404, page('Not found', '<h1>Page not found</h1>'));
    }
  } catch (error) {
    if (error.status === 413) {
      html(res, 413, page('Request too large', '<h1>Request too large</h1>'));
    } else {
      console.error(error);
      html(res, 500, page('Server error', '<h1>Server error</h1>'));
    }
  }
});

server.listen(Number(process.env.PORT || 8080), '0.0.0.0', () => {
  console.log(`Workboard listening on port ${server.address().port}`);
});

for (const signal of ['SIGINT', 'SIGTERM']) {
  process.on(signal, () => server.close(() => {
    db.close();
    process.exit(0);
  }));
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { once } from 'node:events';
import { runInNewContext } from 'node:vm';

async function start(dbPath) {
  const child = spawn(process.execPath, ['server.js'], {
    env: { ...process.env, PORT: '0', DB_PATH: dbPath },
    stdio: ['ignore', 'pipe', 'pipe']
  });
  let output = '';
  let errors = '';
  child.stderr.on('data', chunk => { errors += chunk; });
  const base = await new Promise((resolve, reject) => {
    const timeout = setTimeout(() => {
      child.kill();
      reject(new Error(`Startup timed out: ${errors}`));
    }, 5000);
    child.once('exit', code => {
      clearTimeout(timeout);
      reject(new Error(`Server exited ${code}: ${errors}`));
    });
    child.stdout.on('data', chunk => {
      output += chunk;
      const match = output.match(/listening on port (\d+)/);
      if (match) {
        clearTimeout(timeout);
        resolve(`http://127.0.0.1:${match[1]}`);
      }
    });
  });
  return {
    base,
    async stop() {
      const exited = once(child, 'exit');
      child.kill('SIGTERM');
      await exited;
    }
  };
}

test('project validation, ordering, navigation, escaping and restart persistence', async () => {
  const directory = await mkdtemp(join(tmpdir(), 'workboard-test-'));
  const dbPath = join(directory, 'nested', 'projects.sqlite');
  let server;
  try {
    server = await start(dbPath);
    const health = await fetch(`${server.base}/health`);
    assert.equal(health.status, 200);
    assert.deepEqual(await health.json(), { status: 'ok' });
    const getList = () => fetch(`${server.base}/`).then(response => response.text());
    const create = name => fetch(`${server.base}/projects`, {
      method: 'POST', body: new URLSearchParams({ name }), redirect: 'manual'
    });
    let list = await getList();
    assert.match(list, /<h1>Workboard<\/h1>/);
    assert.match(list, /<label for="project-name">Project name<\/label>/);
    assert.match(list, />Create project<\/button>/);
    assert.doesNotMatch(list, /data-testid="project-row"/);
    for (const name of ['', '  \t  ']) {
      const response = await create(name);
      assert.equal(response.status, 422);
      assert.match(await response.text(), /role="alert">Project name is required/);
    }
    assert.doesNotMatch(await getList(), /data-testid="project-row"/);
    for (const name of ['  First project  ', '<Second & project>']) {
      const response = await create(name);
      assert.equal(response.status, 303);
      assert.equal(response.headers.get('location'), '/');
    }
    list = await getList();
    assert.equal((list.match(/data-testid="project-row"/g) || []).length, 2);
    assert.match(list, /<span>First project<\/span>/);
    assert.match(list, /<span>&lt;Second &amp; project&gt;<\/span>/);
    assert.ok(list.indexOf('First project') < list.indexOf('&lt;Second'));
    const paths = [...list.matchAll(/action="(\/projects\/\d+)"/g)].map(match => match[1]);
    assert.equal(paths.length, 2);
    const detail = await fetch(`${server.base}${paths[0]}`).then(response => response.text());
    assert.match(detail, /<h1>First project<\/h1>/);
    assert.match(detail, /action="\/" method="get"><button type="submit">Projects<\/button>/);
    assert.equal((await fetch(`${server.base}/projects/99999`)).status, 404);
    await server.stop();
    server = await start(dbPath);
    assert.equal(await getList(), list);
    assert.equal(await fetch(`${server.base}${paths[0]}`).then(response => response.text()), detail);
  } finally {
    if (server) await server.stop();
    await rm(directory, { recursive: true, force: true });
  }
});

test('project-scoped tasks, validation, completion, filtering and restart persistence', async () => {
  const directory = await mkdtemp(join(tmpdir(), 'workboard-tasks-'));
  let server;
  try {
    const dbPath = join(directory, 'workboard.sqlite');
    server = await start(dbPath);
    const post = (path, fields) => fetch(`${server.base}${path}`, {
      method: 'POST', body: new URLSearchParams(fields), redirect: 'manual'
    });
    const detail = id => fetch(`${server.base}/projects/${id}`).then(res => res.text());
    await post('/projects', { name: 'First' });
    await post('/projects', { name: 'Second' });
    for (const title of ['', ' \t ']) {
      const response = await post('/projects/1/tasks', { title });
      assert.equal(response.status, 422);
      assert.match(await response.text(), /role="alert"[^>]*>Task title is required/);
    }
    assert.doesNotMatch(await detail(1), /data-testid="task-row">/);
    for (const title of ['  Alpha  ', '<Beta & "quoted">']) {
      const response = await post('/projects/1/tasks', { title });
      assert.equal(response.status, 303);
      assert.equal(response.headers.get('location'), '/projects/1');
    }
    await post('/projects/2/tasks', { title: 'Other task' });
    let content = await detail(1);
    assert.equal((content.match(/data-testid="task-row">/g) || []).length, 2);
    assert.match(content, /<span>Alpha<\/span>/);
    assert.match(content, /aria-label="Complete &lt;Beta &amp; &quot;quoted&quot;&gt;"/);
    assert.ok(content.indexOf('<span>Alpha') < content.indexOf('<span>&lt;Beta'));
    assert.doesNotMatch(content, /Other task/);
    assert.doesNotMatch(await detail(2), /Complete Alpha/);
    assert.doesNotMatch(content, / checked/);
    assert.match(content, /<label for="task-title">Task title<\/label>/);
    assert.match(content, /<label for="task-filter">Task filter<\/label>/);
    assert.match(content, /<option>All<\/option><option>Open<\/option><option>Completed<\/option>/);
    assert.equal((await post('/projects/2/tasks/1/completion', { completed: 'true' })).status, 404);
    assert.equal((await post('/projects/1/tasks/1/completion', { completed: 'invalid' })).status, 400);
    assert.equal((await post('/projects/1/tasks/1/completion', { completed: 'true' })).status, 204);
    content = await detail(1);
    assert.match(content, /tasks\/1\/completion" checked/);

    // Execute the browser script with a minimal DOM to check filtering and saves.
    const filter = { value: 'All', addEventListener(type, handler) { this.change = handler; } };
    const alert = { textContent: '' };
    const rows = [true, false].map((checked, index) => {
      const checkbox = {
        checked, dataset: { completionUrl: `/projects/1/tasks/${index + 1}/completion` },
        addEventListener(type, handler) { this.change = handler; }
      };
      return { checkbox, querySelector() { return checkbox; }, hidden: false };
    });
    let saveOk = true;
    runInNewContext(content.match(/<script>([\s\S]*?)<\/script>/)[1], {
      URLSearchParams,
      document: {
        getElementById: id => id === 'task-filter' ? filter : alert,
        querySelectorAll: selector => selector === '[data-testid="task-row"]' ? rows : rows.map(row => row.checkbox)
      },
      fetch: async (path, options) => {
        assert.equal(path, '/projects/1/tasks/1/completion');
        assert.equal(options.body.get('completed'), 'false');
        return { ok: saveOk };
      }
    });
    filter.change();
    assert.deepEqual(rows.map(row => row.hidden), [false, false]);
    filter.value = 'Open';
    filter.change();
    assert.deepEqual(rows.map(row => row.hidden), [true, false]);
    filter.value = 'Completed';
    filter.change();
    assert.deepEqual(rows.map(row => row.hidden), [false, true]);
    rows[0].checkbox.checked = false;
    await rows[0].checkbox.change();
    assert.deepEqual(rows.map(row => row.hidden), [true, true]);
    saveOk = false;
    rows[0].checkbox.checked = false;
    await rows[0].checkbox.change();
    assert.equal(rows[0].checkbox.checked, true);
    assert.match(alert.textContent, /Could not save/);

    await server.stop();
    server = await start(dbPath);
    assert.equal(await detail(1), content);
    assert.match(await detail(2), /Other task/);
    assert.equal((await post('/projects/1/tasks/1/completion', { completed: 'false' })).status, 204);
    assert.doesNotMatch(await detail(1), / checked/);
    await server.stop();
    server = await start(dbPath);
    assert.doesNotMatch(await detail(1), / checked/);
  } finally {
    if (server) await server.stop();
    await rm(directory, { recursive: true, force: true });
  }
});

